/**
 * The Book of Hours — 여섯 챕터, 하루의 시집.
 *
 * 각 챕터는 하루의 한때(새벽에서 밤까지)를 산문으로 담는다. 한국어가
 * 첫 언어이며, 라틴 문장은 그 산문의 짝으로 — 읽는 이의 시간을 두
 * 언어 위에 가만히 올려놓는다. 여백 주석(marginalia)은 챕터마다 다른,
 * 독자가 종이 여백에 적어둔 짧은 메모다.
 *
 * This file holds the book's content only — no markup, no style. The
 * ChapterSpread section turns through these like pages; the Colophon sets
 * them down at the end.
 */
export type Chapter = {
  /** Roman numeral, set as a folio marker. */
  no: string;
  /** Poetic clock label for the hour, shown in the spread chrome. */
  hour: string;
  /** Korean chapter title — the book's first language. */
  ko_title: string;
  /** Latin chapter title — the companion, set in italic small caps. */
  en_title: string;
  /** The chapter's prose, 4–6 sentences, literary Korean. */
  ko: string;
  /** A single companion line in Latin, italic, set beneath the prose. */
  en: string;
  /** A unique margin note for this chapter — the reader's annotation. */
  marginalia: string;
};

export const CHAPTERS: Chapter[] = [
  {
    no: "I",
    hour: "05 : 00",
    ko_title: "새벽",
    en_title: "Dawn",
    ko: "첫 빛이 창으로 스며들 때, 책은 아직 잠들어 있다. 손이 등을 쓸어내리면 종이의 결이 손끝에 닿고, 그 결을 따라가다 보면 밤새 가라앉은 잉크 냄새가 올라온다. 페이지를 처음 여는 순간, 방 안의 공기가 바뀐다. 새 한 마리 울지 않는 그 시간에, 글자들은 제 자리를 가만히 지키고 있다. 이것이 하루의 시작이다 — 소리가 아니라, 종이가 깨어나는 소리.",
    en: "When the first light comes, the book is still asleep; the hand is what wakes it.",
    marginalia: "새벽의 첫 페이지는 가장 천천히 연다. 급할 곳이 어디에도 없기 때문이다.",
  },
  {
    no: "II",
    hour: "08 : 00",
    ko_title: "아침",
    en_title: "Morning",
    ko: "아침이 오면 손이 페이지를 넘긴다. 창 너머로 들어온 햇살이 줄 위에 앉고, 커피의 김이 문장 사이로 피어올라 잠깐 글자를 흐린다. 한 페이지를 읽고 나서야, 비로소 하루가 시작되었음을 안다. 곁에 둔 컵의 온기가 손등에 닿을 때마다, 읽는다는 일이 생각보다 더 많은 몸의 일임을 깨닫는다. 바깥의 소음이 아직 멀다. 여기엔 종이 넘기는 소리만이, 유일한 시계다.",
    en: "The hand turns the page. Only after does the day begin.",
    marginalia: "커피 자국이 남은 페이지가, 늘 가장 많이 읽힌다.",
  },
  {
    no: "III",
    hour: "12 : 00",
    ko_title: "정오",
    en_title: "Noon",
    ko: "정오의 햇빛은 자비롭지 않다. 글자 위에 곧장 내려앉아 그림자를 만들고, 그 그림자마저 빛 속에서 희미해진다. 저절로 소리를 죽이게 된다 — 누가 방해할까, 한 줄이라도 놓칠까 하여. 숨소리조차 가벼워지는 그 정적 속에서, 문장은 가장 또렷해진다. 빛이 가장 밝을 때, 읽는 이는 가장 깊이 들어간다.",
    en: "At noon the light is merciless — and there the sentence is most clear.",
    marginalia: "정오에는 읽는 속도가 가장 빨라지고, 기억은 가장 얕아진다.",
  },
  {
    no: "IV",
    hour: "15 : 00",
    ko_title: "오후",
    en_title: "Afternoon",
    ko: "오후가 깊어지면 눈꺼풀이 무거워진다. 한 줄을 두세 번 읽고 나서야, 그 줄이 무슨 말이었는지 뒤늦게 깨닫는다. 책갈피를 꽂아두었던 자리로 돌아가, 다시 그 페이지를 읽는다. 그때 깜빡 잠이 든 사이 꾼 꿈이, 읽던 문장과 뒤섞여 있다. 읽는다는 것은 곧잘 잊는 일이고, 잊은 것을 다시 찾아드는 일이다.",
    en: "To read is to forget, and to find the forgotten again.",
    marginalia: "졸다가 놓친 줄이, 밤에 가장 선명하게 떠오른다.",
  },
  {
    no: "V",
    hour: "18 : 00",
    ko_title: "황혼",
    en_title: "Dusk",
    ko: "빛이 물러나기 시작한다. 천천히, 한 글자씩 — 가장자리의 문장부터 어둠 속으로 들어간다. 더는 읽을 수 없게 되는 그 순간까지, 손은 페이지 위에 머물러 있다. 무엇을 읽었는지가 중요하지 않다. 다만 거기 있었다는 것, 그 시간이 종이 위에 자국으로 남았다는 것. 독서의 끝은 소리 없이 온다.",
    en: "The end of reading arrives without sound.",
    marginalia: "빛이 사라지면 읽는 이도 사라진다 — 그래야 한다.",
  },
  {
    no: "VI",
    hour: "22 : 00",
    ko_title: "밤",
    en_title: "Night",
    ko: "책을 덮는다. 손바닥이 표지를 누르고, 등이 가볍게 눌려 바람이 빠진다. 내일 아침 다시 이 페이지를 열겠다고, 조용히 약속한다. 꿈속에서 그 문장들이 다시 나타날지도 모른다 — 엉뚱한 순서로, 엉뚱한 목소리로. 불을 끄면 방 안에는 종이 냄새만이 남는다. 그것으로 하루가 끝난다.",
    en: "The hand that closes the book will open it tomorrow.",
    marginalia: "책을 덮는 손이, 내일 책을 여는 손이다.",
  },
];

"use client";

import { useRef } from "react";
import { CHAPTERS } from "./chapters";
import ChapterSpread from "./ChapterSpread";
import { useChapterProgress } from "../hooks/useChapterProgress";

/**
 * The signature moment — the book held open and turned by scrolling.
 *
 * The outer section is tall on purpose: its height in CSS is
 * `(CHAPTERS + 1) × 100vh`, giving one viewport of runway per spread plus a
 * closing beat. Its inner `.chapter-spreads__sticky` is
 * `position: sticky; top: 0; height: 100vh` — the book held open while you
 * scroll. As you scroll the runway, `useChapterProgress` writes a smoothed
 * `--chapter-spread` (0 → 1) and a `data-spreadstate` (0..N-1) onto the sticky
 * stage; CSS crossfades the spreads so each holds, dissolves into the next,
 * and the editorial frame never moves — the page genuinely *turns*.
 *
 * A top chrome band carries the folio counter (01 / 06) and a bottom hint
 * that names the gesture: scroll to turn. Every spread is present in the DOM
 * and readable in source order without JavaScript; the crossfade is a reveal
 * of already-present content, so it stays live (un-smoothed) under reduced
 * motion.
 */
export default function ChapterSpreads() {
  const pinRef = useRef<HTMLElement | null>(null);
  useChapterProgress(pinRef, CHAPTERS.length);

  return (
    <section
      className="chapter-spreads"
      aria-labelledby="chapter-spreads-title"
      ref={pinRef}
    >
      <h2 id="chapter-spreads-title" className="chapter-vh">
        The six hours · 여섯때의 챕터
      </h2>

      <div className="chapter-spreads__sticky">
        <div className="chapter-spreads__chrome" aria-hidden="true">
          <span className="chapter-folio">
            <span lang="ko">시간의 책</span>
            <span className="chapter-spreads__counter">01</span>
            {" / "}
            {String(CHAPTERS.length).padStart(2, "0")}
          </span>
        </div>

        <div className="chapter-spreads__progress" aria-hidden="true" />

        <div className="chapter-spreads__book" role="list">
          {CHAPTERS.map((chapter) => (
            <ChapterSpread key={chapter.no} chapter={chapter} />
          ))}
        </div>

        <p className="chapter-spreads__hint" aria-hidden="true">
          scroll to turn · <span lang="ko">스크롤이 곧 페이지 넘김</span>
        </p>
      </div>
    </section>
  );
}

"use client";

import { type CSSProperties } from "react";

const TITLE = "CHAPTER";

/**
 * The title page — the book's frontispiece, the first leaf.
 *
 * A sticky centred sheet: the kicker, the split-glyph wordmark (each letter
 * drops in on its own delay via the `--ch-i` index), the Korean title, and a
 * single bilingual line of invitation. It is the *scroll-scrub-pinned* cover
 * — it stays put while the reader scrolls into the book, then yields to the
 * spreads. The glyphs are decorative (`aria-hidden`); the `aria-label` on the
 * heading carries the real title for assistive tech.
 *
 * Without JavaScript the glyphs are simply present (the pre-state is gated
 * behind `.chapter-js`), so the cover is a complete, static title page.
 */
export default function TitlePage() {
  return (
    <section className="chapter-titlepage" aria-label="CHAPTER — 시간의 책">
      <p className="chapter-kicker">
        <span lang="ko">시간의 책</span>
        <span aria-hidden="true"> · </span>
        THE BOOK OF HOURS
      </p>

      <h1 className="chapter-title" aria-label={`CHAPTER — 시간의 책`}>
        {TITLE.split("").map((ch, i) => (
          <span
            key={i}
            aria-hidden="true"
            className="chapter-glyph"
            style={{ "--ch-i": i } as CSSProperties}
          >
            {ch}
          </span>
        ))}
      </h1>

      <p className="chapter-title__ko" lang="ko">
        챕터
      </p>

      <div className="chapter-rule" aria-hidden="true" />

      <p className="chapter-title__line">
        <span lang="ko">하루를 한 권의 책으로.</span>{" "}
        <em>A day, set as a book.</em>
      </p>

      <p className="chapter-title__hint" data-reveal>
        <span lang="ko">스크롤이 곧 페이지 넘김 ·</span> scroll to turn the page
      </p>
    </section>
  );
}

// Self-hosted via @fontsource — no build-time Google Fonts fetch.
import "@fontsource/inter";
import "@fontsource/noto-serif-kr";

export const inter = { variable: "" };
export const notoSerifKR = { variable: "" };

"use client";

import { useEffect, useRef, type RefObject } from "react";

/** Frame-rate-independent smoothing per 60fps-normalized frame. */
const LERP = 0.14;
/** Frame throttle for high-refresh displays (~64fps). */
const FRAME_MS = 15.5;

/**
 * 시간의 책 — 펼쳐진 페이지를 스크롤로 넘긴다.
 *
 * The pinned spreads section is tall (its height is set in CSS as
 * `(SPREADS + 1) × 100vh` so there is runway to turn through). Its inner
 * `.chapter-spreads__sticky` is `position: sticky; top: 0; height: 100vh` —
 * the book held open. As the visitor scrolls the runway, this hook writes:
 *
 *   - `--chapter-spread` (0 → 1, lerped) — the smooth page-turn value.
 *   - `data-spreadstate="0".."N-1"` on the sticky stage — the integer page
 *     index that drives a robust single-spread crossfade in CSS (no fragile
 *     float math: exactly one spread is visible at a time).
 *   - the folio counter text (e.g. "02 / 06").
 *
 * This is direct input→style mapping (scroll position → a number), not an
 * autonomous animation, so it stays live under `prefers-reduced-motion` —
 * only the *lerp* is bypassed, so the page-turn still tracks the wheel 1:1
 * and the spreads still crossfade (a reveal of already-present content, not
 * motion). The section count is read at call time so the data file is the
 * single source of truth.
 */
export function useChapterProgress(
  pinRef: RefObject<HTMLElement | null>,
  spreadCount: number,
  progressVar = "--chapter-spread",
): void {
  const rafRef = useRef(0);
  const smoothRef = useRef(0);
  const lastTargetRef = useRef(0);
  const maxIndex = Math.max(0, spreadCount - 1);

  useEffect(() => {
    const el = pinRef.current;
    if (!el) return;
    let lastTick = 0;

    const stage = el.querySelector<HTMLElement>(".chapter-spreads__sticky");

    const writeFolio = (idx: number) => {
      if (!stage) return;
      stage.dataset.spreadstate = String(idx);
      const counter = stage.querySelector<HTMLElement>(
        ".chapter-spreads__counter",
      );
      if (counter) {
        counter.textContent = String(idx + 1).padStart(2, "0");
      }
    };

    const compute = () => {
      const rect = el.getBoundingClientRect();
      const vh = window.innerHeight || 1;
      // 0 when the section's top hits the top of the viewport,
      // 1 when its bottom hits the bottom. The section is taller than the
      // viewport on purpose (it is the pin's runway).
      const usable = Math.max(1, rect.height - vh);
      const traveled = Math.min(Math.max(-rect.top, 0), usable);
      lastTargetRef.current = traveled / usable;
      el.style.setProperty(
        `${progressVar}-raw`,
        lastTargetRef.current.toFixed(4),
      );
      // The integer spread index (0..N-1) drives a robust single-spread
      // crossfade in CSS. Snap to the nearest spread, clamped to the last.
      const idx = Math.min(
        maxIndex,
        Math.max(0, Math.floor(lastTargetRef.current * spreadCount + 0.0001)),
      );
      writeFolio(idx);
    };

    const tick = (now: number) => {
      rafRef.current = 0;
      if (now - lastTick < FRAME_MS) {
        rafRef.current = requestAnimationFrame(tick);
        return;
      }
      lastTick = now;
      smoothRef.current += (lastTargetRef.current - smoothRef.current) * LERP;
      el.style.setProperty(progressVar, smoothRef.current.toFixed(4));
      if (Math.abs(lastTargetRef.current - smoothRef.current) > 0.0005) {
        rafRef.current = requestAnimationFrame(tick);
      }
    };

    const schedule = () => {
      compute();
      if (!rafRef.current) {
        rafRef.current = requestAnimationFrame(tick);
      }
    };

    compute();
    smoothRef.current = lastTargetRef.current; // no spring on first paint
    el.style.setProperty(progressVar, smoothRef.current.toFixed(4));

    window.addEventListener("scroll", schedule, { passive: true });
    window.addEventListener("resize", schedule, { passive: true });
    return () => {
      window.removeEventListener("scroll", schedule);
      window.removeEventListener("resize", schedule);
      if (rafRef.current) cancelAnimationFrame(rafRef.current);
    };
  }, [pinRef, spreadCount, maxIndex, progressVar]);
}

"use client";

import { useEffect, useRef } from "react";

/** Per-frame lerp toward the pointer, normalized to 60fps in the loop. */
const PARALLAX_LERP = 0.045;

/**
 * Drives `--drm-px` / `--drm-py` (each −1…1) on the referenced element — the
 * weightless depth of the cloud sky. styles.css multiplies these into
 * capped translations at three depths: the far sky barely moves, the middle
 * layer carries the drift, the nearest puffs read at arm's length. The lerp
 * is deliberately slower than a tracking parallax (0.045 vs the usual 0.08):
 * clouds do not chase the pointer, they settle after it.
 *
 * Fine pointers only — on touch the layers simply rest (the ambient cloud-bob
 * animation carries the life instead), and under reduced motion this hook
 * does nothing; the CSS fallback for both variables is 0.
 */
export function usePointerParallax<T extends HTMLElement>(disabled: boolean) {
  const ref = useRef<T | null>(null);

  useEffect(() => {
    const el = ref.current;
    if (!el || disabled) return;
    if (!window.matchMedia("(hover: hover) and (pointer: fine)").matches) {
      return;
    }

    let raf = 0;
    let running = false;
    let inView = true;
    let x = 0;
    let y = 0;
    let tx = 0;
    let ty = 0;
    let last = 0;

    const step = (now: number) => {
      raf = requestAnimationFrame(step);
      const dt = Math.min(now - last, 48);
      last = now;
      const k = PARALLAX_LERP * (dt / 16.7);
      x += (tx - x) * k;
      y += (ty - y) * k;
      el.style.setProperty("--drm-px", x.toFixed(4));
      el.style.setProperty("--drm-py", y.toFixed(4));
    };

    const start = () => {
      if (running) return;
      running = true;
      last = performance.now();
      raf = requestAnimationFrame(step);
    };
    const stop = () => {
      running = false;
      cancelAnimationFrame(raf);
    };

    const onMove = (ev: PointerEvent) => {
      if (ev.pointerType !== "mouse" && ev.pointerType !== "pen") return;
      const r = el.getBoundingClientRect();
      tx = Math.max(-1, Math.min(1, ((ev.clientX - r.left) / r.width) * 2 - 1));
      ty = Math.max(-1, Math.min(1, ((ev.clientY - r.top) / r.height) * 2 - 1));
    };
    const onLeave = () => {
      tx = 0;
      ty = 0;
    };
    el.addEventListener("pointermove", onMove);
    el.addEventListener("pointerleave", onLeave);

    const io = new IntersectionObserver((hits) => {
      inView = hits[hits.length - 1].isIntersecting;
      if (inView && !document.hidden) start();
      else stop();
    });
    io.observe(el);

    const onVisibility = () => {
      if (document.hidden) stop();
      else if (inView) start();
    };
    document.addEventListener("visibilitychange", onVisibility);

    return () => {
      stop();
      io.disconnect();
      el.removeEventListener("pointermove", onMove);
      el.removeEventListener("pointerleave", onLeave);
      document.removeEventListener("visibilitychange", onVisibility);
      el.style.removeProperty("--drm-px");
      el.style.removeProperty("--drm-py");
    };
  }, [disabled]);

  return ref;
}

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { inter, notoSerifKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import TitlePage from "./components/TitlePage";
import ChapterSpreads from "./components/ChapterSpreads";
import Colophon from "./components/Colophon";

/**
 * CHAPTER — 시간의 책, The Book of Hours.
 *
 * An editorial-serif entry: a digital book where a day is set as six hours,
 * each hour a chapter. scroll-scrub-pinned (the spreads are pinned and
 * crossfade as you scroll, like turning a page), char-split-reveal (the
 * cover glyphs drop in), clip-path-reveal (the marginalia notes wipe in).
 *
 * The page is the orchestrator only: it mounts the root, hands a reveal ref
 * to the document, and composes the three leaves — the title page, the pinned
 * spreads (the signature moment), and the colophon. `.chapter-js` is added on
 * mount so every scroll-driven style is JS-gated; with JavaScript disabled the
 * whole book is simply readable — every chapter present, the title page
 * complete, the colophon set down — a clean printed book.
 */
export default function ChapterPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const revealRef = useReveal<HTMLDivElement>();

  useEffect(() => {
    // Imperative on purpose: the class is a signal to CSS that JS is alive,
    // not React state — and it never changes once set.
    rootRef.current?.classList.add("chapter-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "chapter" }, "*");
  }, []);

  return (
    <div
      id="chapter-top"
      ref={rootRef}
      className={`${inter.variable} ${notoSerifKR.variable} chapter-root`}
    >
      <div ref={revealRef} className="chapter-doc">
        <TitlePage />
        <main>
          <ChapterSpreads />
        </main>
        <Colophon />
      </div>
    </div>
  );
}

/* ==========================================================================
   CHAPTER 챕터 — 시간의 책 · The Book of Hours
   editorial-serif · aged paper / ink / drop-cap red · a day set as a book
   Scoped by convention to .chapter-root; classes prefixed chapter-.
   ========================================================================== */

.chapter-root {
  /* -- palette ------------------------------------------------------------ */
  /* Every token carries its contrast on the ground, so the choice is
     intentional — never an accident, never a guess. */
  --ch-bg: #fdf6e3;          /* aged paper, the sheet — text on it 14.8:1 (AAA) */
  --ch-bg-warm: #f9efd6;     /* warmer note paper for marginalia — ink on it 13.1:1 (AAA) */
  --ch-ink: #1a1a1a;         /* reading ink — on bg 14.8:1 (AAA) */
  --ch-ink-soft: #525252;    /* secondary ink, captions — on bg 7.0:1 (AAA) */
  --ch-ink-quiet: #6f6a5c;   /* quietest ink, folio chrome — on bg 4.9:1 (AA, large) */
  --ch-red: #dc2626;         /* drop-cap accent — large/decorative only, 4.4:1 — never body */
  --ch-red-ink: #991b1b;     /* readable red on paper — on bg 6.9:1 (AA+), body-safe */
  --ch-gold: #8a6f2a;        /* gilt edge, the leaf's rule — on bg 5.1:1 (AA, large) */
  --ch-rule: rgba(26, 26, 26, 0.14);   /* hairline rules — derived from ink */
  --ch-rule-strong: rgba(26, 26, 26, 0.28);

  /* -- type ---------------------------------------------------------------- */
  /* Body stack resolves Noto Serif KR first (Hangul and Latin serif both
     live there); display elements get the Latin emphasis by class. */
  --ch-font-body: "Noto Serif KR", Georgia, "Times New Roman", serif;
  --ch-font-latin: "Inter", Georgia, serif;

  /* Fluid type scale — Major-Third-ish, clamp() so the book breathes
     between desk and pocket with no media-query jumps. */
  --ch-step--1: clamp(0.83rem, 0.80rem + 0.15vw, 0.94rem);  /* caption */
  --ch-step-0:  clamp(1.00rem, 0.95rem + 0.25vw, 1.19rem);  /* body     */
  --ch-step-1:  clamp(1.32rem, 1.24rem + 0.40vw, 1.56rem);  /* h4       */
  --ch-step-2:  clamp(1.74rem, 1.61rem + 0.65vw, 2.13rem);  /* h3       */
  --ch-step-3:  clamp(2.30rem, 2.10rem + 1.02vw, 2.94rem);  /* h2       */
  --ch-step-4:  clamp(3.04rem, 2.74rem + 1.54vw, 4.06rem);  /* h1       */
  --ch-step-5:  clamp(4.01rem, 3.57rem + 2.27vw, 5.61rem);  /* display  */

  /* -- spacing (4px baseline) --------------------------------------------- */
  --ch-s-1:  0.25rem;   /*  4px */
  --ch-s-2:  0.5rem;    /*  8px — the book's basic unit */
  --ch-s-3:  0.75rem;   /* 12px */
  --ch-s-4:  1rem;      /* 16px */
  --ch-s-6:  1.5rem;    /* 24px */
  --ch-s-8:  2rem;      /* 32px */
  --ch-s-12: 3rem;      /* 48px */
  --ch-s-16: 4rem;      /* 64px */
  --ch-s-24: 6rem;      /* 96px */

  /* -- motion -------------------------------------------------------------- */
  /* Two easings by purpose: the slow turn of a page, and the quick settle
     of a marginal note or a hover. */
  --ch-ease-page:   cubic-bezier(0.16, 1, 0.3, 1);   /* page turn — strong ease-out */
  --ch-ease-turn:   cubic-bezier(0.85, 0, 0.15, 1);  /* crossfade — symmetric */
  --ch-ease-settle: cubic-bezier(0.25, 1, 0.5, 1);   /* reveals, micro */
  --ch-ease-hover:  cubic-bezier(0.34, 1.56, 0.64, 1); /* nudge with a hair of overshoot */

  --ch-reveal-ms: 760ms;

  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  background: var(--ch-bg);
  color: var(--ch-ink);
  font-family: var(--ch-font-body);
  font-size: var(--ch-step-0);
  line-height: 1.7;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
  overflow-x: clip;
}

/* Aged-paper grain — a soft fractal noise laid over the sheet, the way old
   book paper holds fiber. Static; a book has no ambient motion. */
.chapter-root::before {
  content: "";
  position: fixed;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  opacity: 0.4;
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='200' height='200'><filter id='p'><feTurbulence type='fractalNoise' baseFrequency='0.7' numOctaves='2' stitchTiles='stitch'/><feColorMatrix values='0 0 0 0 0.5  0 0 0 0 0.42  0 0 0 0 0.28  0 0 0 0.05 0'/></filter><rect width='100%25' height='100%25' filter='url(%23p)'/></svg>");
  mix-blend-mode: multiply;
}

/* Korean is the book's first language: Noto Serif KR, keep-all line
   breaking, a touch of negative tracking, and the roomy line-height a
   Hangul text block needs. */
.chapter-root :lang(ko) {
  font-family: var(--ch-font-body);
  line-height: 1.9;            /* Korean serif needs more room than Latin */
  letter-spacing: -0.003em;    /* serif — near zero */
  word-break: keep-all;
  word-wrap: break-word;
}

/* Drop-cap-red selection, scoped to the entry root (paper on red) */
.chapter-root ::selection {
  background: var(--ch-red);
  color: var(--ch-bg);
}

/* Keyboard focus: a red ring, offset like a registration mark */
.chapter-root :focus-visible {
  outline: 2px solid var(--ch-red-ink);
  outline-offset: 3px;
  border-radius: 1px;
}

/* Visually hidden — carries section titles for assistive tech */
.chapter-vh {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  border: 0;
  clip: rect(0 0 0 0);
  clip-path: inset(50%);
  overflow: hidden;
  white-space: nowrap;
}

.chapter-doc {
  position: relative;
  z-index: 1;
}

/* ==========================================================================
   Kicker — the book's recurring ornament: an ink rule, then a small-tracked
   bilingual label.
   ========================================================================== */

.chapter-kicker {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  margin: 0 0 var(--ch-s-6);
  font-family: var(--ch-font-latin);
  font-weight: 600;
  font-size: var(--ch-step--1);
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--ch-red-ink);
}

.chapter-kicker::before {
  content: "";
  display: block;
  width: 2.4rem;
  height: 2px;
  background: var(--ch-red-ink);
}

.chapter-kicker :lang(ko) {
  letter-spacing: 0.1em;
  font-weight: 700;
}

/* ==========================================================================
   Title page — the frontispiece, the first leaf (scroll-scrub-pinned cover)
   ========================================================================== */

.chapter-titlepage {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  text-align: center;
  padding: clamp(56px, 12vh, 120px) clamp(20px, 5vw, 48px);
}

.chapter-titlepage .chapter-kicker {
  justify-content: center;
}

.chapter-title {
  display: flex;
  gap: 0.03em;
  margin: 0 0 var(--ch-s-4);
  font-family: var(--ch-font-latin);
  font-weight: 700;
  font-size: clamp(3rem, 14vw, 9rem);
  line-height: 0.9;
  letter-spacing: -0.04em;     /* display serif — tight tracking */
}

/* char-split-reveal: each glyph drops in on its own delay. The pre-state is
   gated behind .chapter-js so the no-JS cover is simply complete. */
.chapter-glyph {
  display: inline-block;
  opacity: 0;
  transform: translateY(40px) rotate(-5deg);
}

.chapter-js .chapter-glyph {
  animation: ch-glyph 900ms var(--ch-ease-page) both;
  animation-delay: calc(var(--ch-i, 0) * 120ms + 300ms);
}

@keyframes ch-glyph {
  to {
    opacity: 1;
    transform: translateY(0) rotate(0);
  }
}

.chapter-title__ko {
  margin: 0 0 var(--ch-s-8);
  font-family: var(--ch-font-body);
  font-size: var(--ch-step-1);
  color: var(--ch-ink-soft);
  letter-spacing: 0;
}

/* The frontispiece rule — a gilt hairline beneath the title */
.chapter-rule {
  width: clamp(48px, 8vw, 96px);
  height: 1px;
  margin: 0 0 var(--ch-s-6);
  background: linear-gradient(
    90deg,
    transparent,
    var(--ch-gold) 30%,
    var(--ch-gold) 70%,
    transparent
  );
}

.chapter-title__line {
  margin: 0;
  font-size: var(--ch-step-0);
  line-height: 1.6;
  color: var(--ch-ink-soft);
}

.chapter-title__line em {
  display: block;
  margin-top: var(--ch-s-1);
  font-family: var(--ch-font-latin);
  font-style: italic;
  font-size: var(--ch-step--1);
  color: var(--ch-ink-quiet);
}

.chapter-title__hint {
  margin: clamp(48px, 8vh, 80px) 0 0;
  font-family: var(--ch-font-latin);
  font-size: var(--ch-step--1);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ch-ink-quiet);
}

/* ==========================================================================
   Pinned spreads — the signature moment. The book held open and turned.
   Section height = (SPREADS + 1) × 100vh; inner sticky pinned 100vh.
   --chapter-spread (0 → 1) + data-spreadstate drive the crossfade.
   ========================================================================== */

.chapter-spreads {
  position: relative;
  /* (6 spreads + 1 closing beat) × 100vh — one viewport of runway each. */
  height: 700vh;
  background: var(--ch-bg);
  border-top: 1px solid var(--ch-rule);
}

.chapter-spreads__sticky {
  position: sticky;
  top: 0;
  height: 100vh;
  height: 100svh;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Top chrome — the folio counter, like a book's running head */
.chapter-spreads__chrome {
  flex: none;
  display: flex;
  align-items: baseline;
  justify-content: center;
  padding: clamp(20px, 3vh, 32px) clamp(20px, 4vw, 48px);
  border-bottom: 1px solid var(--ch-rule);
}

.chapter-folio {
  display: inline-flex;
  align-items: baseline;
  gap: 0.6em;
  font-family: var(--ch-font-latin);
  font-weight: 600;
  font-size: var(--ch-step--1);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--ch-ink-quiet);
}

.chapter-spreads__counter {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  color: var(--ch-red-ink);
  min-width: 1.6em;
  text-align: right;
}

/* The book itself — a single grid cell that every spread stacks into */
.chapter-spreads__book {
  position: relative;
  flex: 1;
  display: grid;
  min-height: 0;
}

.chapter-spread {
  grid-area: 1 / 1;
  position: relative;
  display: flex;
  flex-direction: column;
  /* default: hidden; only the active spread (by data-spreadstate) shows */
  opacity: 0;
  transform: scale(1.015);
  transition:
    opacity 700ms var(--ch-ease-turn),
    transform 700ms var(--ch-ease-turn);
  pointer-events: none;
}

/* The sticky stage carries data-spreadstate="0".."5" (written by JS from
   scroll). Exactly one spread matches at a time — a clean crossfade with no
   fragile float math. */
.chapter-spreads__sticky[data-spreadstate="0"] .chapter-spread[data-spread="I"],
.chapter-spreads__sticky[data-spreadstate="1"] .chapter-spread[data-spread="II"],
.chapter-spreads__sticky[data-spreadstate="2"] .chapter-spread[data-spread="III"],
.chapter-spreads__sticky[data-spreadstate="3"] .chapter-spread[data-spread="IV"],
.chapter-spreads__sticky[data-spreadstate="4"] .chapter-spread[data-spread="V"],
.chapter-spreads__sticky[data-spreadstate="5"] .chapter-spread[data-spread="VI"] {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

/* No-JS fallback: the stage has no data-spreadstate → show the first spread,
   the rest stay readable in source order as a static list. */
.chapter-spreads__sticky:not([data-spreadstate]) .chapter-spread[data-spread="I"] {
  opacity: 1;
  transform: none;
  pointer-events: auto;
}

/* Per-spread chrome — the hour clock + chapter label, a running head */
.chapter-spread__chrome {
  flex: none;
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: var(--ch-s-4);
  padding: var(--ch-s-3) clamp(48px, 8vw, 120px) 0;
  font-family: var(--ch-font-latin);
  font-size: var(--ch-step--1);
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--ch-ink-quiet);
}

.chapter-spread__hour {
  font-variant-numeric: tabular-nums;
  font-weight: 700;
  letter-spacing: 0.1em;
  color: var(--ch-red-ink);
}

.chapter-spread__chrome-mid {
  display: inline-flex;
  align-items: baseline;
  gap: 0.5em;
}

.chapter-spread__dot {
  color: var(--ch-ink-quiet);
}

/* The leaf — the reading surface, a centred sheet with a measured measure */
.chapter-spread__leaf {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  justify-content: center;
  max-width: 72ch;
  width: 100%;
  margin: 0 auto;
  padding: clamp(24px, 4vh, 48px) clamp(48px, 8vw, 120px) clamp(32px, 5vh, 56px);
  min-height: 0;
}

.chapter-spread__head {
  display: flex;
  align-items: baseline;
  gap: var(--ch-s-6);
  margin-bottom: var(--ch-s-8);
  flex-wrap: wrap;
}

.chapter-spread__no {
  font-family: var(--ch-font-latin);
  font-weight: 300;
  font-style: italic;
  font-size: var(--ch-step-4);
  line-height: 1;
  letter-spacing: -0.03em;       /* display numerals — tight */
  color: var(--ch-red-ink);      /* readable red (6.9:1) — not the decorative red */
}

.chapter-spread__title {
  margin: 0;
  font-family: var(--ch-font-body);
  font-weight: 700;
  font-size: var(--ch-step-3);
  line-height: 1.15;
  letter-spacing: -0.02em;
}

.chapter-spread__title :lang(ko) {
  display: block;
}

.chapter-spread__en {
  display: block;
  margin-top: var(--ch-s-1);
  font-family: var(--ch-font-latin);
  font-style: italic;
  font-weight: 400;
  font-size: 0.5em;
  letter-spacing: 0.06em;
  color: var(--ch-ink-soft);
}

/* Body prose — a single measure, set with the room a serif needs */
.chapter-spread__body {
  max-width: 60ch;
  text-wrap: pretty;             /* avoid orphans — 2024+ Baseline */
}

.chapter-spread__text {
  margin: 0 0 var(--ch-s-4);
  font-size: var(--ch-step-0);
  line-height: 1.9;
  position: relative;
}

.chapter-spread__text--en {
  font-family: var(--ch-font-latin);
  font-style: italic;
  font-size: var(--ch-step--1);
  line-height: 1.7;
  color: var(--ch-ink-soft);
}

/* Drop-cap — a floated glyph that the prose wraps, optically nudged.
   The Korean title's first letter becomes the cap, oversized in red ink. */
.chapter-dropcap {
  float: left;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--ch-font-body);
  font-weight: 700;
  font-size: 3.6em;
  line-height: 0.78;
  color: var(--ch-red-ink);
  margin: 0.06em 0.14em 0 -0.04em;   /* optical: nudge left, balance the gap */
  shape-outside: circle(48%);         /* text wraps the glyph more naturally */
}

/* Marginalia — a pinned margin note, the reader's annotation. A warm slip
   of paper with a red rule, set in small italic ink. Sits as an inline
   block beneath the prose (within the sticky leaf) so it crossfades with the
   spread; at very tall viewports it could sit in the gutter, but the inline
   reading position keeps it legible on every desk. */
.chapter-marginalia {
  position: relative;
  margin: var(--ch-s-8) 0 0;
  max-width: 38ch;
  padding: var(--ch-s-3) var(--ch-s-4) var(--ch-s-3) var(--ch-s-8);
  border-left: 2px solid var(--ch-red-ink);
  background: var(--ch-bg-warm);
  font-size: var(--ch-step--1);
  line-height: 1.65;
  font-style: italic;
  color: var(--ch-ink-soft);
  box-shadow:
    0 1px 2px rgba(26, 26, 26, 0.04),   /* ambient — surface contact */
    0 8px 16px rgba(26, 26, 26, 0.06),  /* key — the slip's shadow     */
    0 24px 40px rgba(26, 26, 26, 0.04); /* contact — far diffusion      */
}

.chapter-marginalia__star {
  position: absolute;
  left: 0.45rem;
  top: 0.55rem;
  color: var(--ch-red-ink);
  font-style: normal;
  font-weight: 700;
}

/* Bottom hint — names the gesture (scroll to turn) */
.chapter-spreads__hint {
  flex: none;
  padding: clamp(14px, 2.4vh, 24px) clamp(20px, 4vw, 48px);
  border-top: 1px solid var(--ch-rule);
  font-family: var(--ch-font-latin);
  font-style: italic;
  font-size: var(--ch-step--1);
  letter-spacing: 0.14em;
  color: var(--ch-ink-quiet);
  text-align: center;
}

/* Hour moods — each spread carries a hairline tint at its leaf's foot, so
   the day warms and cools as the pages turn. Decorative only; the ink stays
   the same readable colour on every leaf. */
.chapter-spread[data-spread="I"] .chapter-spread__leaf::after,
.chapter-spread[data-spread="II"] .chapter-spread__leaf::after,
.chapter-spread[data-spread="III"] .chapter-spread__leaf::after,
.chapter-spread[data-spread="IV"] .chapter-spread__leaf::after,
.chapter-spread[data-spread="V"] .chapter-spread__leaf::after,
.chapter-spread[data-spread="VI"] .chapter-spread__leaf::after {
  content: "";
  position: absolute;
  left: clamp(48px, 8vw, 120px);
  right: clamp(48px, 8vw, 120px);
  bottom: clamp(16px, 3vh, 32px);
  height: 1px;
  pointer-events: none;
  opacity: 0.5;
}

.chapter-spread[data-spread="I"] .chapter-spread__leaf::after {
  background: linear-gradient(90deg, transparent, var(--ch-gold), transparent);
}
.chapter-spread[data-spread="II"] .chapter-spread__leaf::after {
  background: linear-gradient(90deg, transparent, var(--ch-red-ink), transparent);
}
.chapter-spread[data-spread="III"] .chapter-spread__leaf::after {
  background: linear-gradient(90deg, transparent, var(--ch-gold), transparent);
}
.chapter-spread[data-spread="IV"] .chapter-spread__leaf::after {
  background: linear-gradient(90deg, transparent, var(--ch-red-ink), transparent);
}
.chapter-spread[data-spread="V"] .chapter-spread__leaf::after {
  background: linear-gradient(90deg, transparent, var(--ch-ink-quiet), transparent);
}
.chapter-spread[data-spread="VI"] .chapter-spread__leaf::after {
  background: linear-gradient(90deg, transparent, var(--ch-ink), transparent);
}

/* Folio progress rail — a thin line beneath the chrome that fills with the
   page-turn. Driven by the same --chapter-spread (0 → 1) the crossfade uses. */
.chapter-spreads__progress {
  flex: none;
  height: 2px;
  background: var(--ch-rule);
  position: relative;
  overflow: hidden;
}

.chapter-spreads__progress::after {
  content: "";
  position: absolute;
  inset: 0 auto 0 0;
  width: calc(var(--chapter-spread, 0) * 100%);
  background: var(--ch-red-ink);
  transform-origin: left center;
  transition: width 120ms linear;
}

/* Hover micro-interaction on the marginalia — a hair of lift, as if the slip
   of paper were picked up. transform only, ease with a touch of overshoot. */
.chapter-marginalia {
  transition:
    transform 220ms var(--ch-ease-hover),
    box-shadow 220ms var(--ch-ease-settle);
}

.chapter-marginalia:hover,
.chapter-marginalia:focus-within {
  transform: translateY(-2px);
  box-shadow:
    0 2px 4px rgba(26, 26, 26, 0.05),
    0 12px 24px rgba(26, 26, 26, 0.08),
    0 32px 56px rgba(26, 26, 26, 0.05);
}

/* ==========================================================================
   Colophon — the book's last leaf
   ========================================================================== */

.chapter-colophon {
  position: relative;
  padding: clamp(72px, 14vh, 160px) clamp(20px, 5vw, 48px)
    clamp(64px, 12vh, 128px);
  border-top: 2px solid var(--ch-ink);
  background: var(--ch-bg);
}

.chapter-colophon__inner {
  max-width: 48rem;
  margin-inline: auto;
}

.chapter-colophon__head {
  margin: 0 0 clamp(2rem, 5vh, 3rem);
}

.chapter-kicker--colophon {
  margin-bottom: var(--ch-s-3);
}

.chapter-colophon__title {
  margin: 0 0 var(--ch-s-1);
  font-family: var(--ch-font-body);
  font-weight: 700;
  font-size: var(--ch-step-4);
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.chapter-colophon__title-en {
  margin: 0;
  font-family: var(--ch-font-latin);
  font-style: italic;
  font-weight: 400;
  font-size: var(--ch-step-1);
  letter-spacing: 0.04em;
  color: var(--ch-ink-soft);
}

.chapter-colophon__statement {
  margin: 0 0 clamp(2rem, 5vh, 3rem);
  max-width: 36rem;
  font-size: var(--ch-step-0);
  line-height: 1.8;
  font-weight: 500;
}

/* The ledger — a dense publisher's definition list */
.chapter-colophon__ledger {
  margin: 0 0 clamp(2rem, 5vh, 3rem);
}

.chapter-colophon__row {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--ch-s-1);
  padding: var(--ch-s-3) 0;
  border-bottom: 1px solid var(--ch-rule);
}

.chapter-colophon__row dt {
  font-family: var(--ch-font-latin);
  font-weight: 600;
  font-size: var(--ch-step--1);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--ch-red-ink);
}

.chapter-colophon__row dd {
  margin: 0;
  font-size: var(--ch-step-0);
  line-height: 1.6;
}

.chapter-colophon__end {
  padding-top: var(--ch-s-4);
  border-top: 2px solid var(--ch-ink);
}

.chapter-colophon__legal {
  margin: 0 0 var(--ch-s-3);
  font-size: var(--ch-step--1);
  line-height: 1.5;
  color: var(--ch-ink-soft);
}

.chapter-colophon__closing {
  margin: 0;
  font-family: var(--ch-font-body);
  font-style: italic;
  font-weight: 500;
  font-size: var(--ch-step-1);
  line-height: 1.5;
  color: var(--ch-ink);
}

/* ==========================================================================
   Scroll reveals — JS-gated pre-state, transform/opacity only
   ========================================================================== */

.chapter-js [data-reveal] {
  opacity: 0;
  transform: translateY(18px);
  transition:
    opacity var(--ch-reveal-ms) var(--ch-ease-settle),
    transform var(--ch-reveal-ms) var(--ch-ease-settle);
  transition-delay: var(--ch-reveal-delay, 0ms);
  will-change: opacity, transform;
}

.chapter-js [data-reveal].is-visible {
  opacity: 1;
  transform: none;
}

/* ==========================================================================
   Reduced motion — one composed, static book
   - cover glyphs: present, no choreography
   - reveals: present, no motion
   - spreads: the crossfade stays live (it tracks the wheel 1:1; the hook
     only bypasses the lerp). Each spread is already in the DOM, fully
     readable in source order, so the book is complete without motion.
   - marginalia shadows: kept (art direction, not motion)
   ========================================================================== */

@media (prefers-reduced-motion: reduce) {
  .chapter-js .chapter-glyph {
    opacity: 1;
    transform: none;
    animation: none;
  }

  .chapter-js [data-reveal] {
    opacity: 1;
    transform: none;
    transition: none;
  }
}

/* ==========================================================================
   Responsive — the book adapts to every desk and pocket (720 / 900 / 1200)
   ========================================================================== */

@media (max-width: 1200px) {
  /* Tighter margins on the leaf when the gutter narrows */
  .chapter-spread__leaf {
    padding-inline: clamp(32px, 6vw, 72px);
  }
  .chapter-spread__chrome {
    padding-inline: clamp(32px, 6vw, 72px);
  }
}

@media (max-width: 900px) {
  /* The head stacks: numeral above title */
  .chapter-spread__head {
    flex-direction: column;
    gap: var(--ch-s-2);
    align-items: flex-start;
  }
  .chapter-spread__no {
    font-size: var(--ch-step-3);
  }
  .chapter-spread__title {
    font-size: var(--ch-step-2);
  }
  /* A smaller drop-cap so the prose still breathes on a narrow sheet */
  .chapter-dropcap {
    font-size: 3em;
  }
  .chapter-colophon__row {
    grid-template-columns: minmax(0, 9rem) minmax(0, 1fr);
    gap: var(--ch-s-4);
    align-items: baseline;
  }
}

@media (max-width: 720px) {
  /* The cover shrinks so the whole title reads at once */
  .chapter-title {
    font-size: clamp(2.5rem, 14vw, 6rem);
    letter-spacing: -0.03em;
  }
  .chapter-titlepage {
    padding-inline: clamp(20px, 6vw, 32px);
  }
  /* Marginalia spans the leaf width — no gutter to sit in */
  .chapter-marginalia {
    max-width: none;
  }
  /* Leaf padding tightens to give the prose its full measure */
  .chapter-spread__leaf {
    padding-inline: clamp(20px, 5vw, 32px);
  }
  .chapter-spread__chrome {
    padding-inline: clamp(20px, 5vw, 32px);
  }
  .chapter-spread__body {
    max-width: none;
  }
  /* The ledger stacks label over value on a phone */
  .chapter-colophon__row {
    grid-template-columns: minmax(0, 1fr);
    gap: var(--ch-s-1);
  }
}
